import { Plugin } from 'ckeditor5/src/core';
import { ClickObserver } from 'ckeditor5/src/engine';
import { Widget, toWidget } from 'ckeditor5/src/widget';

import '../../theme/file.css';

export default class FileEditing extends Plugin {
	static get requires() {
		return [ Widget ];
	}

	static get pluginName() {
		return 'FileEditing';
	}

	init() {
		const editor = this.editor;
		const schema = editor.model.schema;
		const conversion = editor.conversion;

		schema.register( 'file', {
			allowWhere: '$block',
			isObject: true
		} );
		schema.register( 'fileInnerWrapper', {
			allowIn: 'file'
		} );
		schema.register( 'fileName', {
			allowIn: 'fileInnerWrapper',
			allowAttributes: [ 'name' ]
		} );
		schema.register( 'fileActionButtonsContainer', {
			allowIn: 'fileInnerWrapper'
		} );
		schema.register( 'downloadButton', {
			allowIn: 'fileActionButtonsContainer',
			allowAttributes: [ 'href' ]
		} );
		schema.register( 'deleteButton', {
			allowIn: 'fileActionButtonsContainer'
		} );

		// <file> and <fileInnerWrapper> convertors
		conversion.for( 'upcast' ).elementToElement( {
			model: 'file',
			view: {
				name: 'div',
				classes: 'ck-file'
			}
		} );
		conversion.for( 'dataDowncast' ).elementToElement( {
			model: 'file',
			view: ( modelElement, { writer } ) => {
				const div = writer.createContainerElement( 'div', { class: 'ck-file' } );
				return div;
			}
		} );
		conversion.for( 'editingDowncast' ).elementToElement( {
			model: 'file',
			view: ( modelElement, { writer } ) => {
				const div = writer.createContainerElement( 'div', { class: 'ck-file' } );
				return toWidget( div, writer );
			}
		} );
		conversion.elementToElement( {
			model: 'fileInnerWrapper',
			view: {
				name: 'div',
				classes: 'ck-file-inner-wrapper'
			}
		} );

		// <fileName> convertors
		conversion.for( 'upcast' ).elementToElement( {
			model: ( viewElement, { writer } ) => {
				const name = viewElement.getChild( 0 ).data;
				return writer.createElement( 'fileName', { name } );
			},
			view: {
				name: 'span',
				classes: 'ck-file-name'
			}
		} );
		conversion.for( 'downcast' ).elementToStructure( {
			model: 'fileName',
			view: ( modelElement, { writer } ) => _createFileNameStructure( modelElement, writer )
		} );

		// <fileActionButtonsContainer>, <downloadButton>, <deleteButton> convertors
		conversion.elementToElement( {
			model: 'fileActionButtonsContainer',
			view: {
				name: 'div',
				classes: 'ck-file-buttons-container'
			}
		} );
		conversion.for( 'upcast' ).elementToElement( {
			model: 'downloadButton',
			view: {
				name: 'a',
				classes: 'ck-file-button-link'
			}
		} ).attributeToAttribute( { view: 'href', model: 'href' } );
		conversion.for( 'downcast' ).elementToElement( {
			model: 'downloadButton',
			view: ( modelElement, { writer } ) => _createDownloadLink( modelElement, writer )
		} ).attributeToAttribute( { model: 'href', view: 'href' } );
		conversion.for( 'upcast' ).elementToElement( {
			model: 'deleteButton',
			view: {
				name: 'button',
				classes: 'ck-file-button-delete'
			}
		} );
		conversion.for( 'downcast' ).elementToElement( {
			model: 'deleteButton',
			view: ( modelElement, { writer } ) => _createDeleteButton( modelElement, writer )
		} );

		// onclick event handler for delete button
		const view = editor.editing.view;
		const viewDocument = view.document;
		const model = editor.model;

		view.addObserver( ClickObserver );

		editor.listenTo( viewDocument, 'click', ( evt, data ) => {
			let target = data.target;
			if ( target.name === 'svg' ) {
				target = target.parent;
			}
			const modelElement = editor.editing.mapper.toModelElement( target );
			if ( modelElement && modelElement.name == 'deleteButton' ) {
				model.change( writer => {
					writer.remove( modelElement.findAncestor( 'file' ) );
				} );
			}
		} );
	}
}

function _createUIElementSVG( path ) {
	return `<svg class="icon" height="16" width="16" viewBox="0 0 16 16">${ path }</svg>`;
}

function _createTooltip( tooltipText ) {
	return `<span class="tooltip-text">${ tooltipText }</span>`;
}

function _createDeleteButton( modelElement, viewWriter ) {
	return viewWriter.createUIElement( 'button', {
		class: 'ck-file-button-delete tooltip'
	}, function( domDoc ) {
		const domEl = this.toDomElement( domDoc );
		const tooltip = _createTooltip( 'Remove' );
		// eslint-disable-next-line max-len
		const icon = _createUIElementSVG( '<path d="M2.03995183,3.5 L1,3.5 C0.723857625,3.5 0.5,3.27614237 0.5,3 C0.5,2.72385763 0.723857625,2.5 1,2.5 L5,2.5 L5,2 C5,1.17185763 5.67185763,0.5 6.5,0.5 L9.5,0.5 C10.3281424,0.5 11,1.17185763 11,2 L11,2.5 L15,2.5 C15.2761424,2.5 15.5,2.72385763 15.5,3 C15.5,3.27614237 15.2761424,3.5 15,3.5 L13.9600771,3.5 L13.0749738,14.1242112 L13.0749583,14.1243977 C13.0098846,14.9019827 12.3600634,15.5 11.58,15.5 L4.42067,15.5 C3.64057767,15.5 2.99070695,14.9019413 2.92572876,14.1242425 L2.03995183,3.5 Z M3.04342135,3.5 L3.92226386,14.0410691 C3.94394479,14.3005598 4.1606632,14.5 4.42067,14.5 L11.58,14.5 C11.8399987,14.5 12.0567206,14.3005553 12.0784417,14.0410023 L12.9566128,3.5 L3.04342135,3.5 Z M6,2.5 L10,2.5 L10,2 C10,1.72414237 9.77585763,1.5 9.5,1.5 L6.5,1.5 C6.22414237,1.5 6,1.72414237 6,2 L6,2.5 Z M7,11.5 C7,11.7761424 6.77614237,12 6.5,12 C6.22385763,12 6,11.7761424 6,11.5 L6,6.5 C6,6.22385763 6.22385763,6 6.5,6 C6.77614237,6 7,6.22385763 7,6.5 L7,11.5 Z M10,11.5 C10,11.7761424 9.77614237,12 9.5,12 C9.22385763,12 9,11.7761424 9,11.5 L9,6.5 C9,6.22385763 9.22385763,6 9.5,6 C9.77614237,6 10,6.22385763 10,6.5 L10,11.5 Z" />' );
		domEl.innerHTML = `${ tooltip }${ icon }`;
		return domEl;
	} );
}

function _createDownloadLink( modelElement, viewWriter ) {
	const href = modelElement.getAttribute( 'href' );
	return viewWriter.createUIElement( 'a', {
		href,
		target: '_blank',
		rel: 'noopener noreferrer',
		class: 'ck-file-button-link tooltip'
	}, function( domDoc ) {
		const domEl = this.toDomElement( domDoc );
		const tooltip = _createTooltip( 'Download' );
		// eslint-disable-next-line max-len
		const icon = _createUIElementSVG( '<path d="M8 1C8.27614 1 8.5 1.22386 8.5 1.5V8.79287L10.9798 6.3131C11.175 6.11784 11.4916 6.11784 11.6869 6.3131C11.8821 6.50837 11.8821 6.82495 11.6869 7.02021L8.35354 10.3535C8.15828 10.5488 7.8417 10.5488 7.64644 10.3535L4.3131 7.02021C4.11784 6.82495 4.11784 6.50837 4.3131 6.3131C4.50837 6.11784 4.82495 6.11784 5.02021 6.3131L7.5 8.79289V1.5C7.5 1.22386 7.72386 1 8 1Z" /><path d="M2.5 10C2.5 9.72386 2.27614 9.5 2 9.5C1.72386 9.5 1.5 9.72386 1.5 10V12.6667C1.5 13.1529 1.69315 13.6192 2.03697 13.963C2.38079 14.3068 2.8471 14.5 3.33333 14.5H12.6667C13.1529 14.5 13.6192 14.3068 13.963 13.963C14.3068 13.6192 14.5 13.1529 14.5 12.6667V10C14.5 9.72386 14.2761 9.5 14 9.5C13.7239 9.5 13.5 9.72386 13.5 10V12.6667C13.5 12.8877 13.4122 13.0996 13.2559 13.2559C13.0996 13.4122 12.8877 13.5 12.6667 13.5H3.33333C3.11232 13.5 2.90036 13.4122 2.74408 13.2559C2.5878 13.0996 2.5 12.8877 2.5 12.6667V10Z" />' );
		domEl.innerHTML = `${ tooltip }${ icon }`;
		return domEl;
	} );
}

function _createPaperclipIcon( viewWriter ) {
	return viewWriter.createUIElement( 'svg', null, function( domDoc ) {
		const svg = domDoc.createElementNS( 'http://www.w3.org/2000/svg', 'svg' );
		svg.setAttribute( 'height', 16 );
		svg.setAttribute( 'width', 16 );
		svg.setAttribute( 'viewBox', '0 0 16 16' );
		svg.setAttribute( 'class', 'icon' );
		// eslint-disable-next-line max-len
		svg.innerHTML = '<path d="M14.2934 7.36678L8.1667 13.4934C7.41613 14.244 6.39815 14.6657 5.3367 14.6657C4.27524 14.6657 3.25726 14.244 2.5067 13.4934C1.75613 12.7429 1.33447 11.7249 1.33447 10.6634C1.33447 9.60199 1.75613 8.58401 2.5067 7.83344L8.63336 1.70678C9.13374 1.2064 9.81239 0.925293 10.52 0.925293C11.2277 0.925293 11.9063 1.2064 12.4067 1.70678C12.9071 2.20715 13.1882 2.88581 13.1882 3.59344C13.1882 4.30108 12.9071 4.97973 12.4067 5.48011L6.27336 11.6068C6.02318 11.857 5.68385 11.9975 5.33003 11.9975C4.97621 11.9975 4.63688 11.857 4.3867 11.6068C4.13651 11.3566 3.99596 11.0173 3.99596 10.6634C3.99596 10.3096 4.13651 9.9703 4.3867 9.72011L10.0467 4.06678" stroke-linecap="round" stroke-linejoin="round"/>';
		return svg;
	} );
}

function _createFileNameStructure( modelElement, viewWriter ) {
	const icon = _createPaperclipIcon( viewWriter );
	const fileName = viewWriter.createText( modelElement.getAttribute( 'name' ) );
	const span = viewWriter.createContainerElement( 'span', { class: 'ck-file-name' }, [ fileName ] );
	return viewWriter.createContainerElement( 'div', { class: 'ck-file-name-container' }, [ icon, span ] );
}
